create table if not exists petra.company_modules (id uuid primary key default gen_random_uuid(), company_id uuid not null references petra.companies(id) on delete cascade, module_key text not null, enabled boolean not null default true, configured boolean not null default true, settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id,module_key));
create table if not exists petra.company_settings (company_id uuid primary key references petra.companies(id) on delete cascade, onboarding_completed boolean not null default true, settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_company_modules_company on petra.company_modules(company_id,module_key);
create or replace function petra.ensure_company_modules(p_company_id uuid) returns void language plpgsql as $$ declare m text; begin if not exists(select 1 from petra.companies where id=p_company_id) then raise exception 'PETRA: company not found'; end if; foreach m in array array['dashboard','commercial','quotes','orders','measurement','technical','production','finishing','logistics','installation','finance','inventory','customers','documents','reports','marketing','automations','assistant'] loop insert into petra.company_modules(company_id,module_key,enabled,configured) values(p_company_id,m,true,true) on conflict(company_id,module_key) do nothing; end loop; insert into petra.company_settings(company_id,onboarding_completed) values(p_company_id,true) on conflict(company_id) do update set onboarding_completed=true,updated_at=now(); end; $$;
do $$ declare c record; begin for c in select id from petra.companies loop perform petra.ensure_company_modules(c.id); end loop; end $$;
create or replace function petra.touch_module_settings_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists trg_company_modules_updated_at on petra.company_modules;
create trigger trg_company_modules_updated_at before update on petra.company_modules for each row execute function petra.touch_module_settings_updated_at();
drop trigger if exists trg_company_settings_updated_at on petra.company_settings;
create trigger trg_company_settings_updated_at before update on petra.company_settings for each row execute function petra.touch_module_settings_updated_at();